var dx = 100;
var dy = 40;
var dz = 50;

var dimS = { x: -50, y: 10, z: 10 };
var dimE = { x: 50, y: 40, z: 40 };
var rotM = { x: 0, y: 0, z: 0 };

var numX = 10;
var numZ = 15;
  objs = [];
  for (let z = -numZ; z < numZ; z++) {
    // rotM.y += PI;
    for (let x = -numX; x < numX; x++) {
var posM = { x: x * dx, y: 0, z: z * dz };
      // rotM.y += PI;
			var dx = sin(frameCount * 0.01) * dimS.x * 0.5 * (x % 2 ? 1 : -1);
      var rotM = { x: dx, y: (x+z)%2===0?0:PI, z: 0 };
      objs.push({posM, dimS, dimE, rotM, clr: random(palette)});
    }
  }

  rotScene = {x: random(-0.2, -0.5), y: random(-0.4, 0.4), z: 0}
}

function doubleClicked() {
