    setup();
  }
}

function draw() {
  background(220);

  // sky bg
  if (true && imgs && imgs.length) {
    push()
    translate(0, 0, -500)
    imageModeimage(imgs[0], map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 50, 0), -imgs[0].height*0.35, imgs[0].width*2.5, imgs[0].height*2.5)
    pop()
  }

  orbitControl();
  ambientLight("white");
  // lights();

  // random rotation
  if (rotScene) {
    rotateX(rotScene.x);
    rotateY(rotScene.y);
    rotateZ(rotScene.z);
  }

var locX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
var locY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;
  pointLight(255, 255, 255, locX, locY, height/2);

