  if (true) {
    push();
    translate(0, 1, 0);
    rotateX(HALF_PI);
    fill(16, 0, 64);
var diam = max(width, height) * 2;
    ellipse(0, 0, diam, diam, 100);
    pop();
  }

  for (let o of objs) {
