function drawPost() {
  push()
  stroke(0, 64)
  for (let y = 2; y < height; y += 3) {
    line(0, y, width, y)
  }
  pop();
}

function drawShape(pos, dimS, dimE, rot = null) {
  push();
  translate(pos.x, pos.y, pos.z);
  if (rot) {
    rotateX(rot.x);
    rotateY(rot.y);
    rotateZ(rot.z);
  }

  beginShape(QUAD_STRIP); // https://p5js.org/reference/#/p5/beginShape

  // boden
  vertex(dimS.x, 0, dimS.z);
  vertex(dimS.x, 0, -dimS.z);
  vertex(dimE.x, 0, dimE.z);
  vertex(dimE.x, 0, -dimE.z);

  // rechte Seite
  vertex(dimE.x, -dimE.y, dimE.z);
  vertex(dimE.x, -dimE.y, -dimE.z);

  // top
  vertex(dimS.x, -dimS.y, dimS.z);
  vertex(dimS.x, -dimS.y, -dimS.z);

  // left
  vertex(dimS.x, 0, dimS.z);
  vertex(dimS.x, 0, -dimS.z);

  endShape();

  if (true) {
    // front
    quad(
      dimS.x,
      0,
      -dimS.z,
      dimE.x,
      0,
      -dimE.z,
      dimE.x,
      -dimE.y,
      -dimE.z,
      dimS.x,
      -dimS.y,
      -dimS.z
    );

    // back
    quad(
      dimS.x,
      0,
      dimS.z,
      dimE.x,
      0,
      dimE.z,
      dimE.x,
      -dimE.y,
      dimE.z,
      dimS.x,
      -dimS.y,
      dimS.z
    );
  }
  pop();
}
